class Solution:
    def searchInsert(self, nums: List[int], target: int) -> int:
        left, right = 0, len(nums)

        # Search for the first index with value >= target
        while left < right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid

        return left

class Solution:
    def mySqrt(self, x: int) -> int:
        if x < 2:
            return x

        left, right = 1, x // 2 + 1
        ans = 1

        while left <= right:
            mid = (left + right) // 2
            sq = mid * mid

            if sq <= x:
                ans = mid
                left = mid + 1
            else:
                right = mid - 1

        return ans

class Solution:
    def search(self, nums: List[int], target: int) -> bool:
        left, right = 0, len(nums) - 1

        while left <= right:
            mid = (left + right) // 2

            if nums[mid] == target:
                return True

            # Ambiguous case caused by duplicates
            if nums[left] == nums[mid] == nums[right]:
                left += 1
                right -= 1
            # Left half is sorted
            elif nums[left] <= nums[mid]:
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            # Right half is sorted
            else:
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1

        return False

class Solution:
    def maxDistance(self, position: List[int], m: int) -> int:
        position.sort()

        def can_place(dist: int) -> bool:
            count = 1
            last = position[0]

            for x in position[1:]:
                if x - last >= dist:
                    count += 1
                    last = x
                    if count >= m:
                        return True

            return False

        left, right = 1, position[-1] - position[0]
        ans = 1

        while left <= right:
            mid = (left + right) // 2
            if can_place(mid):
                ans = mid
                left = mid + 1
            else:
                right = mid - 1

        return ans

import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    m = data[1]
    a = data[2:2 + n]

    def check(x: int) -> bool:
        prev = 0

        for val in a:
            # Maximum value reachable without wrapping is val + x
            # If val can be wrapped around to cover prev, we keep prev unchanged.
            if val + x < m:
                # No wrap-around possible: val must end up in [val, val+x]
                if prev > val + x:
                    return False
                prev = max(prev, val)
            else:
                # Wrap-around is possible. Then val can cover [val, m-1] and [0, (val+x)%m].
                # If prev is in the wrapped range, we can keep prev unchanged.
                wrapped_max = (val + x) % m
                if prev > wrapped_max and prev < val:
                    prev = val

        return True

    left, right = 0, m - 1
    ans = m - 1

    while left <= right:
        mid = (left + right) // 2
        if check(mid):
            ans = mid
            right = mid - 1
        else:
            left = mid + 1

    print(ans)


if __name__ == '__main__':
    solve()
